    @EventHandler( payloadType=CreateCartEvent.class )
    public void handle( CreateCartEvent event) {
	    LOGGER.info("handling CreateCartEvent - " + event );
	    Cart entity = new Cart();
            entity.setCartId( event.getCartId() );
            entity.setCartNumber( event.getCartNumber() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setCurrency( event.getCurrency() );
            entity.setShippingAddress( event.getShippingAddress() );
            entity.setBillingAddress( event.getBillingAddress() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCart( entity );
    }

