    /**
     * Method to retrieve the Cart via an CartPrimaryKey.
     * @param 	id Long
     * @return 	Cart
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Cart handle( FindCartQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getCartId() );
    }
    
    /**
     * Method to retrieve a collection of all Carts
     *
     * @param	query	FindAllCartQuery 
     * @return 	List<Cart> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Cart> handle( FindAllCartQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindCart,
 * but only if the id matches
 *
 * @param		entity	Cart
 */
	protected void emitFindCart( Cart entity ) {
		LOGGER.info("handling emitFindCart" );
		
	    queryUpdateEmitter.emit(FindCartQuery.class,
	                            query -> query.getFilter().getCartId().equals(entity.getCartId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllCart
	 * 
	 * @param		entity	Cart
	 */
	protected void emitFindAllCart( Cart entity ) {
		LOGGER.info("handling emitFindAllCart" );
		
	    queryUpdateEmitter.emit(FindAllCartQuery.class,
	                            query -> true,
	                            entity);
	}

